# Generated by build.py from recipe.yml for recipe pop3-refuse-a-second-session. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'example.com', '--mailbox', 'shop@example.com:shoppass', '--mailbox', 'ann@example.com:annpass', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T report.eml smtp://127.0.0.1:8080/shop.example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "LIST 1" pop3://127.0.0.1:8081/
try { sh two-clients.sh 8081 } finally { Stop-Process $server0 }
